[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>SnapFrame — Capture, Create &amp; Share What You Love</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

:root{
  --purple:#7638FA;
  --orange:#FF7A00;
  --black:#000;
  --white:#fff;
  --gray-50:oklch(98.5% 0 0);
  --gray-100:oklch(96% 0 0);
  --gray-200:oklch(90% 0 0);
  --gray-300:oklch(82% 0 0);
  --gray-400:oklch(65% 0 0);
  --gray-500:oklch(52% 0 0);
  --gray-600:oklch(40% 0 0);
  --gray-700:oklch(28% 0 0);
  --gray-800:oklch(18% 0 0);
  --gray-900:oklch(11% 0 0);
  --gradient-brand:linear-gradient(135deg,var(--purple),var(--orange));
  --gradient-soft:linear-gradient(135deg,oklch(70% 0.12 290),oklch(78% 0.16 55));
  --radius-sm:8px;
  --radius-md:12px;
  --radius-lg:20px;
  --radius-xl:28px;
  --shadow-sm:0 1px 2px rgba(0,0,0,.06);
  --shadow-md:0 4px 12px rgba(0,0,0,.08);
  --shadow-lg:0 8px 30px rgba(0,0,0,.1);
  --font-stack:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;
  --max-width:1200px;
  --header-h:72px;
}

html{scroll-behavior:smooth}
body{font-family:var(--font-stack);color:var(--black);background:var(--white);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
button{cursor:pointer;font-family:inherit;border:none;background:none}

/* ─── HEADER ─── */
.header{
  position:fixed;top:0;left:0;right:0;z-index:100;
  height:var(--header-h);
  background:rgba(255,255,255,.85);
  backdrop-filter:blur(16px);
  -webkit-backdrop-filter:blur(16px);
  border-bottom:1px solid transparent;
  transition:border-color .3s,background .3s;
}
.header.scrolled{border-bottom-color:var(--gray-200);background:rgba(255,255,255,.95)}
.header-inner{
  max-width:var(--max-width);margin:0 auto;padding:0 24px;
  display:flex;align-items:center;justify-content:space-between;height:100%;
}
.header-logo{
  font-size:1.5rem;font-weight:800;letter-spacing:-.02em;
  background:var(--gradient-brand);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
.header-nav{display:flex;align-items:center;gap:32px}
.header-link{font-size:.9rem;font-weight:500;color:var(--gray-700);transition:color .2s}
.header-link:hover{color:var(--black)}
.btn-login{
  padding:10px 24px;border-radius:100px;font-size:.875rem;font-weight:600;
  background:var(--gray-100);color:var(--black);transition:background .2s;
}
.btn-login:hover{background:var(--gray-200)}
.btn-primary{
  padding:14px 32px;border-radius:100px;font-size:1rem;font-weight:600;
  background:var(--gradient-brand);color:var(--white);
  transition:opacity .2s,transform .2s;
  display:inline-flex;align-items:center;gap:8px;
}
.btn-primary:hover{opacity:.9;transform:translateY(-1px)}
.btn-outline{
  padding:14px 32px;border-radius:100px;font-size:1rem;font-weight:600;
  border:2px solid var(--black);color:var(--black);
  transition:background .2s,color .2s;
  display:inline-flex;align-items:center;gap:8px;
}
.btn-outline:hover{background:var(--black);color:var(--white)}
.btn-store{
  display:inline-flex;align-items:center;gap:10px;
  padding:12px 24px;border-radius:var(--radius-md);
  background:var(--black);color:var(--white);font-weight:600;font-size:.875rem;
  transition:opacity .2s;
}
.btn-store:hover{opacity:.85}
.btn-store svg{width:24px;height:24px;flex-shrink:0}
.btn-store span small{display:block;font-size:.65rem;font-weight:400;opacity:.7}

/* ─── HAMBURGER ─── */
.hamburger{display:none;flex-direction:column;gap:5px;padding:8px;z-index:200}
.hamburger span{
  display:block;width:24px;height:2px;background:var(--black);
  border-radius:2px;transition:transform .3s,opacity .3s;
}
.hamburger.active span:nth-child(1){transform:translateY(7px) rotate(45deg)}
.hamburger.active span:nth-child(2){opacity:0}
.hamburger.active span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}

/* ─── MOBILE NAV OVERLAY ─── */
.mobile-nav{
  position:fixed;inset:0;z-index:150;
  background:var(--white);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:32px;
  opacity:0;pointer-events:none;transition:opacity .3s;
}
.mobile-nav.open{opacity:1;pointer-events:auto}
.mobile-nav a{font-size:1.25rem;font-weight:600;color:var(--gray-800)}
.mobile-nav a:hover{color:var(--purple)}

/* ─── HERO ─── */
.hero{
  position:relative;overflow:hidden;
  min-height:100vh;display:flex;align-items:center;justify-content:center;
  padding:120px 24px 80px;text-align:center;
}
.hero-bg{
  position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(ellipse 80% 60% at 20% 30%,oklch(55% 0.22 284 / 15%),transparent),
    radial-gradient(ellipse 60% 50% at 80% 70%,oklch(72% 0.22 55 / 12%),transparent),
    radial-gradient(ellipse 50% 40% at 50% 50%,oklch(48% 0.18 320 / 8%),transparent);
}
.hero-content{position:relative;z-index:1;max-width:800px}
.hero-badge{
  display:inline-block;padding:6px 16px;border-radius:100px;
  background:var(--gray-100);font-size:.8rem;font-weight:600;color:var(--gray-600);
  margin-bottom:24px;letter-spacing:.02em;
}
.hero-title{
  font-size:clamp(2.5rem,6vw,4.5rem);font-weight:900;
  line-height:1.08;letter-spacing:-.03em;margin-bottom:20px;
}
.hero-title span{background:var(--gradient-brand);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text}
.hero-subtitle{
  font-size:clamp(1rem,2vw,1.2rem);color:var(--gray-500);
  max-width:560px;margin:0 auto 36px;line-height:1.6;
}
.hero-actions{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}
.hero-visual{
  margin-top:60px;position:relative;
  display:flex;align-items:center;justify-content:center;gap:16px;flex-wrap:wrap;
}
.hero-card{
  width:180px;height:240px;border-radius:var(--radius-xl);
  background:var(--white);box-shadow:var(--shadow-lg);
  display:flex;align-items:center;justify-content:center;
  font-size:2rem;transition:transform .3s;
}
.hero-card:nth-child(1){transform:rotate(-4deg)}
.hero-card:nth-child(2){transform:rotate(2deg) translateY(-16px)}
.hero-card:nth-child(3){transform:rotate(-2deg) translateY(-8px)}
.hero-card:hover{transform:rotate(0) translateY(-8px)}
.hero-card-inner{
  width:100%;height:100%;border-radius:var(--radius-xl);overflow:hidden;
  background:var(--gradient-soft);
  display:flex;align-items:center;justify-content:center;
}

/* ─── SECTIONS COMMON ─── */
.section{padding:100px 24px}
.section-inner{max-width:var(--max-width);margin:0 auto}
.section-label{
  display:inline-block;font-size:.8rem;font-weight:700;text-transform:uppercase;
  letter-spacing:.06em;margin-bottom:12px;
}
.section-heading{
  font-size:clamp(1.8rem,3.5vw,2.8rem);font-weight:800;
  line-height:1.15;letter-spacing:-.02em;margin-bottom:16px;
}
.section-description{
  font-size:1.05rem;color:var(--gray-500);max-width:600px;line-height:1.65;
}
.section-link{
  display:inline-flex;align-items:center;gap:6px;font-weight:600;font-size:.95rem;
  margin-top:20px;transition:gap .2s;
}
.section-link:hover{gap:12px}
.section-link::after{content:'→';font-size:1.1em}
.section-link.external::after{content:'↗'}

/* ─── FEATURES ─── */
.features-grid{
  display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:48px;
}
.feature-card{
  background:var(--gray-50);border-radius:var(--radius-lg);
  padding:32px 24px;transition:transform .2s,box-shadow .2s;
  border:1px solid var(--gray-100);
}
.feature-card:hover{transform:translateY(-4px);box-shadow:var(--shadow-md)}
.feature-icon{
  width:52px;height:52px;border-radius:var(--radius-md);
  display:flex;align-items:center;justify-content:center;margin-bottom:20px;
  font-size:1.5rem;
}
.feature-icon.clips{background:oklch(55% 0.22 284 / 12%);color:var(--purple)}
.feature-icon.stories{background:oklch(55% 0.22 284 / 12%);color:var(--purple)}
.feature-icon.dms{background:oklch(72% 0.22 55 / 12%);color:var(--orange)}
.feature-icon.explore{background:oklch(72% 0.22 55 / 12%);color:var(--orange)}
.feature-card h3{font-size:1.1rem;font-weight:700;margin-bottom:8px}
.feature-card p{font-size:.9rem;color:var(--gray-500);line-height:1.5}

/* ─── SAFETY ─── */
.safety{background:var(--gray-50)}
.safety .section-inner{
  display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;
}
.safety-visual{
  display:flex;align-items:center;justify-content:center;
}
.safety-shield{
  width:240px;height:280px;border-radius:var(--radius-xl);
  background:linear-gradient(160deg,oklch(90% 0.04 150),oklch(80% 0.08 150));
  display:flex;align-items:center;justify-content:center;position:relative;
}
.safety-shield svg{width:80px;height:80px;color:oklch(55% 0.14 150)}
.safety-tools{
  display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:32px;
}
.safety-tool{
  display:flex;align-items:flex-start;gap:12px;padding:16px;
  background:var(--white);border-radius:var(--radius-md);border:1px solid var(--gray-100);
}
.safety-tool-icon{
  width:36px;height:36px;border-radius:50%;flex-shrink:0;
  background:oklch(60% 0.12 150 / 10%);
  display:flex;align-items:center;justify-content:center;font-size:1rem;
}
.safety-tool h4{font-size:.9rem;font-weight:700;margin-bottom:2px}
.safety-tool p{font-size:.8rem;color:var(--gray-500);line-height:1.4}

/* ─── CREATORS ─── */
.creators .section-inner{
  display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center;
}
.creators-visual{
  display:flex;gap:16px;justify-content:center;order:-1;
}
.creator-stat{
  background:var(--white);border:1px solid var(--gray-100);
  border-radius:var(--radius-lg);padding:28px 24px;text-align:center;
  transition:transform .2s;
}
.creator-stat:hover{transform:translateY(-4px)}
.creator-stat .number{
  font-size:2.4rem;font-weight:900;
  background:var(--gradient-brand);
  -webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;
}
.creator-stat .label{font-size:.8rem;color:var(--gray-500);margin-top:4px}

/* ─── TAGLINE BANNER ─── */
.tagline-banner{
  background:var(--gradient-brand);padding:72px 24px;text-align:center;
  position:relative;overflow:hidden;
}
.tagline-banner::before{
  content:'';position:absolute;inset:0;
  background:radial-gradient(ellipse 60% 80% at 30% 50%,rgba(255,255,255,.12),transparent);
}
.tagline-banner p{
  position:relative;font-size:clamp(1.6rem,3.5vw,2.6rem);font-weight:800;
  color:var(--white);letter-spacing:-.02em;line-height:1.2;max-width:700px;margin:0 auto;
}

/* ─── NEWS ─── */
.news-header{
  display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:32px;flex-wrap:wrap;gap:16px;
}
.news-header .section-label{color:var(--purple)}
.news-view-more{font-weight:600;font-size:.9rem;color:var(--gray-600);display:flex;align-items:center;gap:4px}
.news-view-more:hover{color:var(--black)}
.news-view-more::after{content:'→'}

.news-carousel-wrapper{position:relative}
.news-carousel{
  display:flex;gap:20px;overflow-x:auto;scroll-snap-type:x mandatory;
  scroll-behavior:smooth;-webkit-overflow-scrolling:touch;
  padding-bottom:8px;scrollbar-width:none;
}
.news-carousel::-webkit-scrollbar{display:none}
.news-card{
  flex:0 0 340px;scroll-snap-align:start;
  background:var(--white);border-radius:var(--radius-lg);
  border:1px solid var(--gray-200);overflow:hidden;
  transition:box-shadow .2s,transform .2s;min-width:280px;
}
.news-card:hover{box-shadow:var(--shadow-md);transform:translateY(-2px)}
.news-card-thumb{
  width:100%;height:180px;position:relative;overflow:hidden;
}
.news-card-thumb .thumb-bg{
  width:100%;height:100%;
}
.thumb-1{background:linear-gradient(135deg,oklch(55% 0.18 284),oklch(48% 0.16 320))}
.thumb-2{background:linear-gradient(135deg,oklch(60% 0.18 55),oklch(72% 0.2 65))}
.thumb-3{background:linear-gradient(135deg,oklch(55% 0.16 240),oklch(50% 0.2 270))}
.thumb-4{background:linear-gradient(135deg,oklch(50% 0.16 180),oklch(45% 0.18 200))}
.news-card-body{padding:20px}
.news-card-tags{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}
.news-tag{
  font-size:.7rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em;
  padding:4px 10px;border-radius:100px;
}
.news-tag.announcements{background:oklch(55% 0.22 284 / 10%);color:var(--purple)}
.news-tag.tips{background:oklch(60% 0.18 180 / 10%);color:oklch(48% 0.12 180)}
.news-tag.product{background:oklch(72% 0.22 55 / 10%);color:var(--orange)}
.news-tag.safety{background:oklch(55% 0.14 150 / 10%);color:oklch(48% 0.12 150)}
.news-card-title{font-size:.95rem;font-weight:700;line-height:1.35;margin-bottom:8px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.news-card-date{font-size:.8rem;color:var(--gray-400);font-weight:500}

.carousel-arrows{display:flex;gap:8px;margin-top:16px}
.carousel-arrow{
  width:40px;height:40px;border-radius:50%;border:1px solid var(--gray-200);
  display:flex;align-items:center;justify-content:center;
  background:var(--white);transition:background .2s,border-color .2s;
}
.carousel-arrow:hover{background:var(--gray-50);border-color:var(--gray-300)}
.carousel-arrow svg{width:18px;height:18px}

/* ─── CTA DOWNLOAD ─── */
.cta-download{background:var(--gray-50);text-align:center}
.cta-download .section-heading{margin-bottom:8px}
.cta-download .section-subheading{font-size:1.1rem;color:var(--gray-500);margin-bottom:36px}
.cta-download .store-buttons{display:flex;gap:14px;justify-content:center;flex-wrap:wrap}

/* ─── FOOTER ─── */
.footer{background:var(--black);color:var(--white);padding:72px 24px 40px}
.footer-inner{max-width:var(--max-width);margin:0 auto}
.footer-grid{
  display:grid;grid-template-columns:repeat(6,1fr);gap:40px 20px;
}
.footer-col h4{
  font-size:.75rem;font-weight:700;text-transform:uppercase;
  letter-spacing:.06em;margin-bottom:20px;
  color:var(--white);
}
.footer-col ul{list-style:none;display:flex;flex-direction:column;gap:10px}
.footer-col a{
  font-size:.85rem;color:var(--gray-400);transition:color .2s;
}
.footer-col a:hover{color:var(--white)}
.footer-col a.external::after{content:' ↗';font-size:.75em;opacity:.5}
.footer-bottom{
  margin-top:56px;padding-top:32px;border-top:1px solid var(--gray-800);
  display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:20px;
}
.footer-lang{
  display:flex;align-items:center;gap:8px;font-size:.85rem;color:var(--gray-400);
  cursor:pointer;padding:8px 12px;border-radius:var(--radius-sm);border:1px solid var(--gray-800);
  transition:border-color .2s;
}
.footer-lang:hover{border-color:var(--gray-600)}
.footer-social{display:flex;gap:16px}
.footer-social a{
  width:36px;height:36px;border-radius:50%;background:var(--gray-800);
  display:flex;align-items:center;justify-content:center;
  transition:background .2s;
}
.footer-social a:hover{background:var(--gray-700)}
.footer-social svg{width:16px;height:16px;fill:var(--gray-300)}
.footer-legal{display:flex;gap:20px;flex-wrap:wrap}
.footer-legal a{font-size:.8rem;color:var(--gray-500);transition:color .2s}
.footer-legal a:hover{color:var(--gray-300)}

/* ─── RESPONSIVE ─── */
